@fwdDiff_iter_eq_sum_shift : ∀ {M : Type u_1} {G : Type u_2} [inst : AddCommMonoid M] [inst_1 : AddCommGroup G] (h : M)
  (f : M → G) (n : ℕ) (y : M),
  (fwdDiff h)^[n] f y = ∑ k ∈ Finset.range (n + 1), ((-1) ^ (n - k) * ↑(n.choose k)) • f (y + k • h)
@fwdDiff_iter_degree_eq_factorial : ∀ {R : Type u_1} [inst : CommRing R] (P : R[X]),
  ((fwdDiff 1)^[P.natDegree] fun x => eval x P) = P.leadingCoeff • ↑P.natDegree.factorial
@fwdDiff_iter_eq_zero_of_degree_lt : ∀ {R : Type u_1} [inst : CommRing R] {P : R[X]} {n : ℕ},
  P.natDegree < n → ((fwdDiff 1)^[n] fun x => eval x P) = 0
@fwdDiff_iter_eq_zero_of_degree_lt : ∀ {R : Type u_1} [inst : CommRing R] {P : R[X]} {n : ℕ},
  P.natDegree < n → ((fwdDiff 1)^[n] fun x => eval x P) = 0

